create table if not exists app.compensation_sources (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app.profiles(id) on delete cascade, title text not null, source_url text not null, observed_at timestamptz not null, license_note text, created_at timestamptz not null default now());
create table if not exists app.compensation_benchmarks (id uuid primary key default gen_random_uuid(), source_id uuid references app.compensation_sources(id) on delete set null, title text not null, location text, level text, value numeric not null, currency text not null, period text not null, confidence text not null, observed_at timestamptz not null);
create table if not exists app.compensation_recommendations (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app.profiles(id) on delete cascade, application_id uuid references app.applications(id) on delete cascade, floor numeric not null, target numeric not null, stretch numeric not null, currency text not null, period text not null, confidence text not null, calculation_version text not null, created_at timestamptz not null default now());
alter table app.compensation_sources enable row level security; alter table app.compensation_recommendations enable row level security;
create policy compensation_sources_owner on app.compensation_sources for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy compensation_recommendations_owner on app.compensation_recommendations for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
